cd /tmp && PYTHONPATH=/opt/kv-seed /opt/kv-grader/bin/python - <<'EOF'
import redis, kvdump, json, collections
dump = kvdump.dump_server(6379)
print("dbs:", {db: len(d) for db,d in dump.items()})
print("source digest:", kvdump.digest(dump))
types = collections.Counter()
for db, d in dump.items():
    for k,(t,v,p) in d.items():
        types[t]+=1
print("types:", dict(types))
# count stream groups
for db,d in dump.items():
    for k,(t,v,p) in d.items():
        if t=="stream":
            print("stream", db, k[:40], "groups:", [g[0] for g in v["groups"]], "entries:", len(v["entries"]))
EOF
